    const tips = buildClockAdvice({ level: "fail", skewSec: 120, maxSkewSec: 30 });
    assert.ok(tips.some((t) => /GitHub App JWT|TLS/i.test(t)));
    assert.ok(tips.some((t) => /wsl --shutdown/i.test(t)));
  });
});

